export const editorialPages:Record<string,EditorialPage>={
 '/renovations':make("Home renovations Meath & Navan","Keep what matters.","Change how you live.","Love where you live, but not how the house works? Based in Slane, Co. Meath, Fennor helps homeowners in Navan and across Meath and Louth plan renovations around better layouts, useful space and everyday life. Dublin enquiries are welcome too.","renovation-overview-photoreal-v2-4k.webp",[
 ["First, we get to know your home.","We start with the rooms that frustrate you and the things you want to keep. Together, we separate the essentials from the nice-to-haves and set priorities around your budget."],
 ["Then we look beyond the finish.","Before pricing the work, we identify the surveys needed for structure, damp and existing services. We explain what is known, what still needs investigating and how any allowance affects the price."],
 ["You know what happens next.","We explain the proposed stages, likely disruption and whether rooms can remain in use. Your proposal sets out the work included, any exclusions, payment stages and how changes and handover will be handled."]],["Photos or a rough plan of your home","The things you most want to change","Your budget priorities and whether you plan to stay at home"],[{"q":"Can I live at home during a renovation?","a":"Sometimes. We look at the work involved and explain whether safe cooking, washing, heating and access can be maintained. If a phased approach or temporary move is needed, we talk that through before agreeing the programme."},{"q":"Should I choose finishes before getting a quote?","a":"A few ideas are enough to begin. We help you weigh finishes against your budget and show any allowance for choices you have not made yet."}],{"alt":"Architectural design concept of connected dining, kitchen and garden-facing living spaces","kind":"overview","related":["/renovations/full-home","/renovations/kitchens","/renovations/bathrooms","/renovations/older-homes"]}),
 '/renovations/full-home':make("Full-home renovations","A house you know.","A home rethought.","When several rooms need to change, it helps to plan the house as a whole. Fennor brings your layout, comfort and day-to-day needs into one renovation journey.","renovation-full-home-photoreal-v2-4k.webp",[
 ["A layout that fits the next chapter.","We start with how you cook, work, relax and move through the house. Your priorities guide the brief; measured surveys and the relevant design input establish which layout changes are practical."],
 ["A clear picture of the work involved.","We identify where structural or services advice is needed and explain the findings in plain language. You see the proposed work, allowances and remaining unknowns before deciding how far to take the renovation."],
 ["A plan for living through the work.","We agree access, protection of the areas you are keeping and any temporary arrangements. You receive a written price and programme, with inspections, making good, handover and changes explained rather than left for you to coordinate."]],["Any existing plans or previous alterations","The rooms and routines you want to improve","Whether you need to live at home during the work"],[{"q":"Will the renovation need planning permission?","a":"We identify which checks your proposed changes need and explain who will handle them. Internal alterations do not always need planning permission, but external changes, protected structures and changes of use can. Building-regulation requirements are separate."},{"q":"Can we include energy upgrades?","a":"Yes. We bring insulation, ventilation, heating and suitable solar options into the same plan. We also explain any required grant approval before eligible work starts."}],{"alt":"Connected hallway, dining and kitchen spaces in a coordinated Irish home renovation","related":["/retrofitting/whole-home","/building/extensions","/about/your-project"],"sources":[["Irish building-regulation technical guidance","https://www.gov.ie/en/collection/d9729-technical-guidance-documents/"]]}),
 '/renovations/kitchens':make("Kitchen renovations","Made for cooking.","Designed for living.","A better kitchen starts with the way you use it. Fennor helps you make room for cooking, storage and family life, with the layout and practical work considered together.","renovation-kitchen-photoreal-v2-4k.webp",[
 ["Your routine shapes the layout.","We ask where worktop space runs out, what is hard to reach and how many people use the room. Then we work through storage, seating and appliance positions so your choices serve the room, not just the photograph."],
 ["We explain the work behind each option.","Moving a sink, cooker or extractor changes drainage, electrical loads or ventilation. We identify the specialist input needed and show how those changes affect the price, so you can choose a layout with the full picture."],
 ["From favourite finish to agreed plan.","We help narrow your materials, lighting and fittings around budget and upkeep. The proposal clearly separates removal, fitting, connections, decoration and any items you are supplying. You know what is included before the old kitchen comes out."]],["Photos and approximate kitchen dimensions","Your cooking routine and planned appliances","Storage frustrations and finishes you like"],[{"q":"Do I need a completely different layout?","a":"Not always. We first look at whether better storage, lighting or selected replacements would solve the problem. Keeping suitable services where they are can simplify the work."},{"q":"Can we open the kitchen into another room?","a":"Yes, it is an option to explore. We establish the structural and regulatory checks needed, including support, fire safety and ventilation, before pricing an opening between rooms."}],{"alt":"Practical renovated family kitchen with fitted storage, task lighting and a garden outlook","related":["/renovations/full-home","/building/extensions","/solar/accessories/eddi"]}),
 '/renovations/bathrooms':make("Bathroom renovations","A calmer morning.","A better bathroom.","A better shower, easier cleaning or more room to move. Fennor starts with what would improve your morning, then helps you choose a bathroom that works for the space and the household.","renovation-bathroom-photoreal-v2-4k.webp",[
 ["Fittings that work in your room.","We begin with your layout and daily needs. Water pressure, hot-water capacity, drainage and clearances are checked before the fittings are settled, so the shower you choose is supported by the home around it."],
 ["The hidden work is part of the job.","We include waterproofing, suitable underlying surfaces and ventilation in the plan, not just tiles and taps. Tiles and grout alone are not waterproofing. We explain the specialist work and checks needed before new finishes are fitted."],
 ["Comfort now, easier use later.","We work through reachable controls, slip resistance, storage and cleaning with you. If access is a concern, it becomes part of the brief from the start. Electrical work needs the appropriate specialist, and we retain access to essential valves and wastes."]],["What you would change about the current bathroom","Your shower, bath and storage priorities","Any pressure, access or hot-water concerns"],[{"q":"Could I replace the bath with a walk-in shower?","a":"Often, but the floor, drainage, waterproofing and available space decide what is practical. We establish those checks first and explain the options; a level-access shower cannot be confirmed from a photo alone."},{"q":"Will the project address a bathroom that stays damp?","a":"We start by understanding when and where moisture appears, rather than assuming a new fan will solve it. Any investigation and ventilation work is brought into the plan before new finishes go in."}],{"alt":"Compact renovated family bathroom with bath shower, vanity, frosted window and towel radiator","related":["/retrofitting/ventilation","/renovations/full-home","/heat-pumps/air-to-water"],"sources":[["Irish building-regulation technical guidance","https://www.gov.ie/en/collection/d9729-technical-guidance-documents/"]]}),
 '/renovations/older-homes':make("Renovating older Irish homes","Character retained.","Comfort reconsidered.","Keep the character you fell for and improve the parts that make everyday life harder. Fennor helps you plan an older-home renovation with care for the building and the people living in it.","renovation-older-home-photoreal-v2-4k.webp",[
 ["We start with what is already there.","Original features, past repairs and damp patches all tell us something useful. We identify the surveys needed to understand the walls, roof, floors and ventilation before new work covers them up."],
 ["Improvements that belong in this building.","We bring your comfort and layout goals together with the right specialist advice. Traditional masonry needs compatible insulation, renders and junctions; a product suited to a modern wall may trap moisture in an older one."],
 ["A clear route through the permissions.","We ask about protected status or conservation-area restrictions early. Where planning or conservation advice is needed, we explain the next appointment and its effect on the work before presenting a construction price."]],["What you know about the home’s age and past repairs","Features you love and rooms you want to improve","Any known damp or conservation status"],[{"q":"Could we make an old stone house warmer?","a":"Yes, there may be suitable improvements. We start with a building-specific assessment of construction and moisture, then explain the options. Thickness or an advertised insulation value alone does not establish the right solution."},{"q":"Can an older home have solar or a heat pump?","a":"Age alone does not rule them out. We identify the roof, energy and fabric checks required, alongside any conservation restrictions, and explain which options are worth taking forward."}],{"alt":"Traditional Irish cottage with natural slate, weathered masonry and established hedgerows","sources":[["SEAI: energy efficiency in traditional buildings","https://www.seai.ie/sites/default/files/publications/Energy_Efficiency_in_Traditional_Buildings.pdf"]],"related":["/retrofitting/insulation","/heat-pumps/suitability","/renovations/full-home"]}),
 '/retrofitting':make("Home energy upgrades & retrofitting Meath","Less heat escaping.","More home to enjoy.","Cold rooms, draughts or heating that never seems to catch up? Fennor helps homeowners in Slane, Navan and across Meath and Louth plan insulation, fresh air and heating together. Start with the home you have and the comfort you want.","retrofit-03.webp",[
 ["We start with the rooms you live in.","Tell us where the house feels uncomfortable and what you spend on heating. We look at the information you have, identify the assessment needed and help set priorities around your budget."],
 ["One plan, even if you work in stages.","We connect insulation, windows, ventilation and heating so an improvement now supports the next one. You receive a clear sequence and an explanation of the specialist design needed at each stage."],
 ["You know the next step and the cost.","We explain the proposed work, disruption, individual-grant steps and any items outside the price. Before you decide, we confirm Fennor’s role and any required assessment, specialist or registered-contractor arrangements."]],["The rooms you most want to improve","Any BER, heating bills or upgrade records you have","Your budget priorities and plans for the home"],[{"q":"Must I retrofit everything at once?","a":"No. We help you prioritise what is useful now and plan for later work. The design still needs to keep insulation, ventilation and future heating changes compatible."},{"q":"Will a better BER mean lower bills?","a":"A better BER describes improved assessed performance, not a guaranteed bill. We explain expected outcomes using your heating habits and the assumptions about weather, tariffs, comfort and system use."}],{"alt":"Home retrofitting in Meath, Louth & Dublin — architectural design concept","kind":"overview","sources":[["SEAI individual home-energy grants","https://www.seai.ie/grants/home-energy-grants/individual-grants"]],"related":["/retrofitting/whole-home","/retrofitting/insulation","/retrofitting/windows-doors","/retrofitting/ventilation","/retrofitting/grants-funding"]}),
 '/retrofitting/whole-home':make("Whole-home energy retrofit","One connected plan.","A more comfortable home.","A whole-home upgrade brings warmth, fresh air and heating into one plan. Fennor helps you see the full picture, choose priorities and understand how the work will fit around your life.","retrofit-whole-home-photoreal-v2-4k.webp",[
 ["Your priorities come first.","We begin with the cold rooms, existing upgrades and changes you want to make. The professional assessment establishes the starting condition and tests the options against your budget and comfort goals."],
 ["We connect the work between rooms and trades.","Window edges, wall insulation and roof junctions need to work together. We identify the required design input and explain the order of work, including access and whether you will need temporary accommodation."],
 ["A home you understand at handover.","Before work is agreed, we set out the inspections, commissioning and post-works assessment included. We also explain who will demonstrate the controls, provide maintenance guidance and deal with any remaining items."]],["What a more comfortable home would change for you","Rooms that need to stay usable during work","Any surveys, BER or previous upgrade details"],[{"q":"Can Fennor coordinate several improvements in one plan?","a":"Yes. We connect insulation, ventilation, windows and heating in a sensible sequence, including work that can be phased. Your proposal identifies the work Fennor can cover, the individual-grant conditions to check and any specialist assessment or registered role required."},{"q":"Can we agree a target BER?","a":"Yes. We put your target into the assessment and explain what the proposed work is expected to achieve. The final rating depends on completed work, supporting information and the assessor’s calculation."}],{"alt":"Mineral-wool insulation and airtightness work around a window during a whole-home retrofit","sources":[["SEAI individual home-energy grants","https://www.seai.ie/grants/home-energy-grants/individual-grants"]],"related":["/retrofitting/grants-funding","/heat-pumps/suitability","/about/your-project"]}),
 '/retrofitting/insulation':make("Home & attic insulation Meath","Keep the warmth.","Respect the building.","Warmer rooms begin with understanding where heat escapes. Fennor helps homeowners in Meath choose the next step for an attic, walls or floors, with the building’s condition and your plans in mind.","retrofit-detail-concept.webp",[
 ["Make the attic warmer without losing useful space.","We ask how you use the roof space, then identify the checks needed for existing insulation, ventilation and services. The plan keeps required air paths clear and avoids compressed insulation, whether the space is a cold attic or an occupied room."],
 ["The right approach for your walls.","We explain cavity, internal or external insulation after the relevant survey establishes suitability. Moisture, exposure and wall condition come first. You also see how the work affects window surrounds, sills, roof edges and external fittings."],
 ["Make the most of other planned work.","If floors are opening or windows are changing, we bring insulation into the same plan. We explain the effect on floor levels, thresholds and services before you choose finishes, including the cost and disruption of each option."]],["Where the house feels cold or draughty","Any damp, leaks or previous insulation work","Floors, windows or rooms you plan to change"],[{"q":"How will we choose the insulation?","a":"We use the survey findings and your priorities to explain the suitable options. Thickness is only part of it: moisture, continuity, space, compatible materials and installation details matter too."},{"q":"What if I have damp as well as cold walls?","a":"We identify the investigation needed before covering the wall and explain how any repairs fit into the work. Insulation must not conceal an unresolved moisture problem."}],{"alt":"Home insulation planning — architectural design concept","sources":[["SEAI home upgrade routes","https://www.seai.ie/homeenergyupgrades"],["Traditional-building guidance","https://www.seai.ie/sites/default/files/publications/Energy_Efficiency_in_Traditional_Buildings.pdf"]],"related":["/retrofitting/ventilation","/retrofitting/windows-doors","/renovations/older-homes"]}),
 '/retrofitting/windows-doors':make("Windows & doors grant 2026 | Meath","Frame the view.","Improve the comfort.","Draughty frames, awkward openings or a room that never feels comfortable? Fennor helps you plan energy-efficient windows and doors in Meath around how you live, with the fitting, finishing and current grant conditions explained.","full-home-editorial.webp",[
 ["We work through the rooms with you.","A bedroom, living-room view and busy entrance have different needs. We help you weigh light, opening arrangements, security and upkeep, using whole-window or whole-door performance rather than the glass value alone."],
 ["The finish around the frame matters too.","We explain what happens to sills, plaster, decoration and external finishes. The measurements and installation details address insulation and airtightness while retaining suitable ventilation and escape provisions. You know what making good is included in the price."],
 ["We explain the support available.","SEAI’s individual scheme offers window support by dwelling type, up to €4,000 for a detached home, and €800 per eligible external door, up to two. We take you through the relevant insulation, property-age, performance and post-works BER conditions alongside the proposed work."]],["Photographs of the openings you want to improve","Any BER and wall or attic insulation records","Your priorities for light, security and easier use"],[{"q":"Do I have to replace every window?","a":"Not necessarily under the current individual scheme. We work through the openings you want to change and explain the property-wide requirements. Support is normally paid once per property; scheme eligibility and the appointed contractor’s registration still apply."},{"q":"Will new windows stop the draughts without making the house stuffy?","a":"We plan for both. Tighter windows reduce uncontrolled draughts, but suitable fresh-air provision remains essential. We explain any ventilation changes included with the new windows."}],{"alt":"Architectural design concept of a light-filled home with large garden-facing windows and doors","sources":[["SEAI windows and doors grant","https://www.seai.ie/grants/home-energy-grants/individual-grants/windows-and-doors"]],"related":["/retrofitting/insulation","/retrofitting/ventilation","/retrofitting/grants-funding"]}),
 '/retrofitting/ventilation':make("Home ventilation & MVHR Meath","Keep the warmth.","Make room for fresh air.","Condensation in the morning or a room that always feels stuffy? Fennor helps homeowners in Meath understand the route to a fresher, more comfortable home, from local ventilation to a properly assessed whole-house or heat-recovery system.","window-reveal-editorial.webp",[
 ["First, we understand the problem.","We ask when moisture appears, which rooms are affected and what has changed in the house. That helps identify the professional investigation needed. A new fan is not a guaranteed cure for unexplained moisture or mould."],
 ["Then we explain the suitable options.","The design needs to suit your layout, airtightness and household. We talk you through natural, local mechanical or whole-house options and what each would involve. Heat recovery also requires suitable airtightness, duct design and commissioning."],
 ["You know how to live with the result.","We address fan noise, controls and access for cleaning before the work is agreed. Handover includes the operating and maintenance guidance set out in your proposal, with commissioning results where required."]],["The rooms and times when moisture is noticeable","Photographs of existing fans and vents","Other insulation, window or bathroom work you are planning"],[{"q":"Can I close vents to save heat?","a":"Do not block required ventilation, especially around combustion appliances. Tell us where the draughts are; we identify the appropriate professional assessment so warmth is improved without compromising safety."},{"q":"Does my home need heat-recovery ventilation?","a":"Not automatically. We explain the options established by the assessment, including what they mean for installation, everyday use and maintenance. Airtightness, layout and household needs determine the suitable approach."}],{"alt":"Architectural design concept of a bright interior window opening; ventilation needs a separate designed strategy","sources":[["SEAI home energy upgrades","https://www.seai.ie/homeenergyupgrades"]],"related":["/retrofitting/whole-home","/retrofitting/insulation","/renovations/bathrooms"]}),
 '/retrofitting/grants-funding':make("Retrofit grants and funding in Ireland","Start with your home.","Make sense of the support.","You do not need to choose a grant scheme before you call. Fennor starts with the improvements you want, explains the routes that may apply and helps you understand the steps before work begins.","retrofit-03.webp",[
 ["For improvements made in stages.","We explain which individual grants relate to your planned work and what information the application needs. You make the application and appoint the contractors; we explain the work Fennor would handle, any required registered specialists and the paperwork for your claim."],
 ["For connected improvements.","We bring insulation, windows, heating and ventilation decisions into one Fennor plan, even when the work is phased. Each individual grant keeps its own conditions, application and registered-delivery requirements; your proposal shows what Fennor can cover."],
 ["For a budget you can rely on.","We separate the proposed cost, possible individual support and work that is not grant-funded. Approval must be in place before eligible work starts, and the written offer—not a headline amount—sets the support for your home."]],["Home age, MPRN and any BER you have","Previous grants or applications already in progress","The improvements and budget you want to discuss"],[{"q":"Can Fennor help me decide where to begin?","a":"Yes. Tell us what you want to improve and about any application already underway. We explain the relevant assessment, likely project steps and which funding conditions need to be checked for your home."},{"q":"Can different grants pay for the same work?","a":"The same cost cannot simply be funded twice. We review the support you already have and explain which scheme rules need confirmation before it is included in the project budget."},{"q":"Can Fennor coordinate several grant-supported improvements?","a":"We can plan the work we cover as one connected project and explain the individual-grant sequence. Your proposal identifies each application, required registered role, approval point and item outside Fennor’s scope before you decide."}],{"alt":"Retrofit grants and funding in Ireland — architectural design concept","kind":"guide","sources":[["SEAI individual home-energy grants","https://www.seai.ie/grants/home-energy-grants/individual-grants"]],"related":["/heat-pumps/grants","/retrofitting/windows-doors","/contact/assessment"]}),
 '/heat-pumps':make("Heat pumps Meath & Navan","Comfort, considered.","Heat, reimagined.","Replacing your heating is a big decision. From our Slane base, Fennor helps homeowners in Navan and across Meath and Louth understand whether a heat pump fits their home, what would change and what the full project would involve.","heat-pump-garden-editorial.webp",[
 ["Start with comfort, not a model number.","We ask about cold rooms, heating bills and hot-water use, then review the information you have. We identify the professional assessment needed to establish heat loss and any improvements to the home before equipment is selected."],
 ["See what changes and what stays.","We explain the findings for your radiators, cylinder, controls and available space. The specialist design also addresses outdoor airflow, sound, electrical supply and maintenance access, so you see the whole installation rather than only the outdoor unit."],
 ["Decide with the full picture.","We set out the work, costs, likely disruption and items outside the price. You know who will design, install and commission the system, which grant registrations are required and how the controls and aftercare will be handed over."]],["The rooms and heating costs you want to improve","Any BER, insulation records or recent fuel bills","Photographs of your radiators, cylinder and available space"],[{"q":"Can we discuss a heat pump for an existing home?","a":"Yes. Share your current heating details and what you want to improve. We identify the assessment that will show whether the house is suitable now or what work would help prepare it."},{"q":"Will a heat pump reduce my bills?","a":"We explain the comparison for your home using heat demand, expected performance, electricity tariff and the fuel being replaced. Bills vary with the home and how the system is used, so there is no universal saving."}],{"alt":"Architectural design concept of a brand-neutral air-to-water heat pump beside an Irish home","kind":"overview","sources":[["SEAI heat-pump installation guide","https://www.seai.ie/plan-your-energy-journey/for-your-home/guide-to-upgrades/heat-pumps/installing-heat-pumps"]],"related":["/heat-pumps/air-to-water","/heat-pumps/suitability","/heat-pumps/with-solar","/heat-pumps/grants","/heat-pumps/faq"]}),
 '/heat-pumps/air-to-water':make("Air-to-water heat pumps","From outside air.","To everyday warmth.","An air-to-water heat pump can warm suitable radiators or underfloor heating and provide hot water. Fennor helps you understand the change from your current system, room by room.","heat-pump-concept.webp",[
 ["Understand how your heating would work.","The system uses electricity to move heat from outdoor air into heating water. We explain how that differs from your current setup and the assumptions behind expected running costs. A laboratory efficiency figure is not an annual performance guarantee."],
 ["Keep the radiators that suit the design.","We take you through the heating designer’s findings for each room. Some radiators may stay; others or their pipework may need changing to deliver enough heat at the proposed water temperature. You see the reason and price for each change."],
 ["Know where everything will go.","We work through cylinder space and possible outdoor positions with you. The specialist checks cover airflow, sound, drainage, electrical capacity and service access. We then explain installation, making good, commissioning and the controls demonstration included in the work."]],["Your existing heating and hot-water arrangement","Any room plans, BER or insulation details","Photographs of possible cylinder and outdoor-unit locations"],[{"q":"Will I need underfloor heating?","a":"Not necessarily. Suitably sized radiators can work with a properly designed system. We explain the room-by-room findings and any proposed changes before you decide."},{"q":"Where can the outdoor unit go?","a":"We start with the available space, bedrooms and neighbouring properties, then identify the technical checks needed for sound, airflow, drainage and access. The unit is not silent; a suitable position needs assessment, not just a photograph."}],{"alt":"Air-to-water heat pumps — architectural design concept","related":["/heat-pumps/suitability","/heat-pumps/grants","/retrofitting/insulation"]}),
 '/heat-pumps/suitability':make("Is my home suitable for a heat pump?","A better answer starts","with your home.","Not sure whether your house is ready for a heat pump? You do not have to work that out yourself. Fennor helps you understand the assessment, the results and any improvements needed first.","retrofit-03.webp",[
 ["We make the starting point simple.","Bring a BER or a heating bill if you have one, and tell us which rooms feel cold. We identify the assessment needed for the building’s condition and room-level heat demand. Missing paperwork is not a reason to put off the first call."],
 ["We turn the findings into choices.","We explain what the assessment means for radiators, pipework, cylinder space and electrical supply. If changes will affect storage, floors or decoration, we show those alongside the cost so you can weigh the whole project."],
 ["We explain the grant evidence separately.","A pre-2007 home needs a technical assessment for SEAI’s individual grant unless a valid BER records HLI of 2.3 W/(K·m²) or less. Otherwise eligible homes built from 2007 onward, and qualifying older homes, use self-declaration. The home must be built and occupied before 2021. This paperwork does not replace heating design."]],["Whatever BER or home-age information you have","Your heating bills and the rooms that feel cold","Photographs of radiators, cylinder and available space"],[{"q":"Does a good BER mean the heating design is already done?","a":"No. It is a useful starting record. We explain the additional room-by-room heat-loss, radiator or underfloor-heating checks and installation design your proposed system needs."},{"q":"What if improvements are needed first?","a":"We put the findings into a sensible order and explain the cost of the improvements first. Insulation, ventilation or radiator work may come before the heat pump. The home’s needs, not a grant deadline, determine the sequence."}],{"alt":"Is my home suitable for a heat pump? — architectural design concept","feature":"readiness","sources":[["SEAI heat-pump grant assessment requirements","https://www.seai.ie/grants/home-energy-grants/individual-grants/heat-pump-systems"]],"related":["/retrofitting/whole-home","/heat-pumps/air-to-water","/contact/assessment"]}),
 '/heat-pumps/with-solar':make("Heat pumps with solar PV","Two useful systems.","One considered energy plan.","Solar and a heat pump work on different daily and seasonal patterns. Fennor helps you bring them into one energy plan, with clear priorities for heating, hot water and any battery.","energy-home.webp",[
 ["We plan around the full year.","We look at heating demand alongside the expected solar generation, including winter when heat demand is higher and daylight is lower. The heating design must work without relying on summer surplus being available all year."],
 ["We help make useful use of daytime power.","We work through your hot-water routine and the opportunities to align it with generation. The controls must retain comfort, manufacturer requirements and hygiene settings. An immersion diverter is not automatically more efficient than the heat pump for heating water."],
 ["We give storage a clear purpose.","We explain how much surplus may remain, which loads you want to shift and how the tariff affects value. Battery capacity, power limits and losses are included in that comparison. A domestic battery shifts energy through the day, not from summer into winter."]],["Recent electricity and heating usage","Details of solar or storage already installed","Your daily heating and hot-water routine"],[{"q":"Could solar cover all my winter heating?","a":"Do not assume it will. Winter heating need is generally highest when solar availability is lower. We explain the seasonal balance and the grid electricity your plan still needs to allow for."},{"q":"Can we plan the battery and hot water together?","a":"Yes. We work through the equipment, your hot-water routine and electricity tariff together. The controls need clear priorities, with comfort, export value and efficiency considered and the same solar surplus never counted twice."}],{"alt":"Heat pumps with solar PV — architectural design concept","related":["/solar/domestic","/solar/battery-storage","/solar/accessories/eddi"]}),
 '/heat-pumps/grants':make("Heat-pump grants in Ireland","Useful support.","A clearer next step.","Wondering how much support could apply to your heating upgrade? Fennor explains the separate grant elements, the conditions for your home and the steps from assessment to an agreed project.","heat-pump-concept.webp",[
 ["Here is what the headline includes.","SEAI lists up to €10,500 for an eligible air-to-water heat-pump system, up to €2,000 for qualifying central-heating changes and €2,000 for eligible boiler scrappage. The maximum combined house figure is €14,500; apartment and replacement-system rules differ. We explain which elements relate to your planned work."],
 ["You see the cost and support separately.","We review the existing heating and previous grants, then explain the costs and possible support line by line. Heating changes and scrappage have separate conditions, support cannot exceed eligible work costs, and replacement heat pumps have different limits."],
 ["We explain the approval steps.","The individual scheme requires an MPRN and a home built and occupied before 2021. We clarify the assessment or self-declaration requirement, appointed contractor’s relevant registration and application tasks. Approval is required before work; the SEAI offer determines your award."]],["Your existing heating type and home age","Any BER, assessment or previous grant details","The improvements and budget you want to discuss"],[{"q":"Would my project receive the full €14,500?","a":"Not automatically. €14,500 is the combined maximum for eligible house projects meeting every component’s conditions. We explain the elements relevant to your home; the dwelling, existing system, eligible costs and SEAI offer determine the actual support."},{"q":"Can the heat-pump grant be planned with other improvements?","a":"Yes. We can connect the heating design with planned insulation, windows or ventilation and explain the relevant individual grants. Each measure keeps its own approval and registered-contractor conditions, and the same cost cannot be claimed twice."}],{"alt":"Heat-pump grants in Ireland — architectural design concept","kind":"guide","sources":[["SEAI current heat-pump values and scheme terms","https://www.seai.ie/grants/home-energy-grants/individual-grants/heat-pump-systems"]],"related":["/heat-pumps/suitability","/retrofitting/grants-funding","/contact/assessment"]}),
 '/heat-pumps/faq':make("Heat-pump questions answered","Your home. Your questions.","Let’s make it clearer.","Will the radiators stay warm enough? Will there be enough hot water? What happens to the bills? Fennor gives you clear answers tied to your home, not a one-size-fits-all sales pitch.","heat-pump-concept.webp",[
 ["We explain the changes in everyday terms.","The design may recommend a different radiator, a new cylinder or pipework changes. We explain why each item is needed, what it affects in your home and what it costs, using the heating calculations behind the recommendation."],
 ["You know how to use the heating.","We agree a practical controls demonstration as part of the project. It covers normal schedules, weather compensation and useful settings for the installed system, which is often designed for steady operation rather than repeated large temperature changes."],
 ["You know who to call afterwards.","We explain the warranty, maintenance requirements and aftercare arrangement before you decide. At handover, the agreed records and support contacts come together so a fault or a simple operating question does not leave you searching for the right person."]],["The questions that matter most to your household","Your current heating and hot-water routine","Any worries about running costs, controls or aftercare"],[{"q":"Will the radiators feel as hot as they do now?","a":"Not necessarily. A lower-temperature system can keep rooms comfortable with suitable radiators and longer operating periods. We explain what that means for the proposed system; room comfort matters more than a radiator feeling very hot."},{"q":"Will there be enough hot water?","a":"We include your showers, baths and busy periods in the brief. The designer uses those needs to size the cylinder and plan recovery and controls, including how hot water and space heating share the system."},{"q":"Can I use it like my old boiler?","a":"Some habits may change. We include a demonstration of the installed controls and normal schedules in the agreed handover. Follow that guidance rather than making large setbacks or changing technical settings yourself."},{"q":"How can we understand the running cost before deciding?","a":"We take you through the assumptions for heat demand, water temperature, seasonal performance, tariff and use. The calculator illustrates those relationships; it is not a forecast for your property or a promised saving."}],{"alt":"Heat-pump questions answered — architectural design concept","kind":"guide","related":["/heat-pumps/air-to-water","/heat-pumps/suitability","/heat-pumps/with-solar"]}),
 '/building':make("Builders Meath & Slane","Room for what","comes next.","More room for family life, a place to work or a home built from the ground up. Fennor, based in Slane, helps you plan extensions, attic conversions and new builds in Navan and across Meath and Louth, with Dublin enquiries also welcome.","new-build-concept.webp",[
 ["We begin with what the space is for.","How would the new room change your day? We explore the layout, light, storage and garden connection with you, then separate the priorities from the extras so the brief reflects how you want to live."],
 ["We explain the next design steps.","Bring the drawings you have, or start with the idea. We identify the planning, structural and certification input needed and explain the appointments to be agreed, including how Fennor’s work fits with the architect, engineer and other specialists."],
 ["You receive a price you can follow.","We show the work included, allowances and exclusions against the agreed drawings and specification. We also explain the programme, payment stages, access arrangements and how changes will be priced, so you know the commitments on both sides."]],["Where you want to build and what you need the space for","Any drawings or planning information you already have","Your budget priorities and hoped-for timing"],[{"q":"Can we talk before I have drawings?","a":"Yes. Start with your location and the space you need. We help shape the brief and explain the next design steps. A dependable construction price follows the necessary drawings, specifications and site information."},{"q":"Who will carry out specialist work?","a":"We identify the specialists and explain who is responsible for each part of the project before you agree the work. Regulated tasks require the appropriate qualifications and, where applicable, registration."}],{"alt":"Building and construction in Meath, Louth & Dublin — architectural design concept","kind":"overview","related":["/building/extensions","/building/new-builds","/building/attic-conversions","/about/your-project"],"sources":[["Irish building-regulation technical guidance","https://www.gov.ie/en/collection/d9729-technical-guidance-documents/"]]}),
 '/building/extensions':make("House extensions Meath & Navan","More than more space.","A better connection.","Make the home you love work better for the way you live now. Fennor helps homeowners in Slane, Navan and across Meath plan an extension around the rooms you use, the garden you enjoy and the space you are missing.","extension-photoreal-v2-4k.webp",[
 ["We look at the whole house with you.","A brighter kitchen or family room needs to improve the space around it too. We work through movement, views and privacy, with the design balancing daylight, summer comfort and heat loss for the existing and new rooms."],
 ["We explain the connection work.","Foundations, drainage, structure and services can all change where old meets new. We identify the investigations needed and explain how the house will be protected during construction, including the implications if you want to stay at home."],
 ["We establish the route to building.","We review the drawings, any previous extensions and the planning position with you. Small does not automatically mean exempt. The relevant professional or planning authority establishes the route, and we explain the remaining steps before pricing the agreed work."]],["What you want the new room to do","Any plans, permissions or previous extension details","How you use the house and garden today"],[{"q":"Could we stay in the house during the build?","a":"Sometimes. We explain whether safe access, separation and temporary services can be maintained for your project. The stage where the extension joins the house needs particular planning, which we work through with you in advance."},{"q":"Can we plan for solar at the same time?","a":"Yes. We bring roof layout, shading, cable routes and electrical needs into the planning conversation early. That creates a useful starting point for the solar assessment without assuming a particular system will fit."}],{"alt":"Contemporary garden-facing extension joined to an established Irish home","related":["/renovations/kitchens","/solar/domestic","/building/new-builds"],"sources":[["Irish building-regulation technical guidance","https://www.gov.ie/en/collection/d9729-technical-guidance-documents/"]]}),
 '/building/new-builds':make("New builds Meath & Navan","A new beginning.","Considered from the ground up.","Your new home starts with the way you want to live. Fennor helps clients in Slane, Navan and across Meath turn the site, design and energy plans into a build you understand, from the first price to the handover.","new-build-concept.webp",[
 ["We establish where the project stands.","We review your location, planning position and drawings, then identify the information still needed on ground conditions, access, drainage and services. You know what can be priced and which questions need answers first."],
 ["We connect the house and its systems.","We bring insulation, ventilation, heating and any solar or charging plans into the build conversation together. Working from the relevant design information, we identify plant space and service routes early, rather than leaving them to become alterations later."],
 ["We make the build commitments clear.","Before you decide, we explain the price, allowances, payment stages and expected sequence. You know the professional and certification appointments involved, what Fennor will deliver and how inspections, changes and handover are handled."]],["Your site location and planning position","Any design drawings or site investigations","The spaces and energy features that matter most to you"],[{"q":"Can I start by sharing images of homes I like?","a":"Absolutely. They help us understand the proportions, materials and spaces you like. We then explain the drawings, specification and site information needed to turn that direction into a dependable construction price."},{"q":"Should I include retrofit grants in a new-build budget?","a":"Not unless eligibility is confirmed. Many energy grants depend on when the home was built and occupied. We keep unconfirmed support out of the build budget and explain the terms that need to be checked."}],{"alt":"New-build homes — architectural design concept","related":["/solar/domestic","/heat-pumps","/about/your-project"],"sources":[["Irish building-regulation technical guidance","https://www.gov.ie/en/collection/d9729-technical-guidance-documents/"]]}),
 '/building/attic-conversions':make("Attic conversions Meath & Navan","Space above.","Possibility within.","Could the space upstairs become somewhere useful? Fennor helps homeowners in Slane, Navan and across Meath explore an attic’s potential, with a clear answer on the assessment needed, the effect downstairs and the work involved.","attic-photoreal-v2-4k.webp",[
 ["We find out what the space can offer.","Tell us whether you want a bedroom, workspace or storage. We identify the measured and structural assessments needed for headroom, the roof and floor support. Existing ceiling joists are not assumed suitable for a habitable floor."],
 ["We work through the staircase and safe use.","We explain how access would affect the floor below and what the professional fire-safety and escape review needs to establish. A storage conversion and a compliant bedroom are different jobs; you know which use is being designed and priced."],
 ["We plan for a comfortable room.","We bring insulation, ventilation, summer heat and sound separation into the brief alongside rooflights and finishes. We also identify any planning checks and access needed to existing services, then set out the complete proposed work and price."]],["The room you would like to create","Any safely available photographs or measurements","Your thoughts on stairs, storage and existing services"],[{"q":"Could my attic become a bedroom?","a":"It depends on the available space and required structure, stairs and fire-safety provisions. We explain the feasibility assessment first, so you have a sound basis for deciding whether to take a bedroom design forward."},{"q":"Would an attic project need planning permission?","a":"The property and external changes determine that. We identify the relevant planning checks and explain the next step. Planning permission and building-regulation compliance remain separate requirements."}],{"alt":"Finished attic study with a guarded staircase, fitted eaves storage and natural roof light","related":["/retrofitting/insulation","/renovations/full-home","/contact/assessment"],"sources":[["Irish building-regulation technical guidance","https://www.gov.ie/en/collection/d9729-technical-guidance-documents/"]]}),
 '/about':make("About Fennor Developments","Local roots.","A personal approach.","We are Fennor, a family-run business rooted in Slane, Co. Meath. We help homeowners and businesses plan solar, renovations and building improvements with straightforward advice and a personal approach.","slane-bridge-boyne.webp",[
 ["It starts with listening.","Your project might begin with a high electricity bill, a cold room or simply needing more space. We take time to understand the problem and what a good result would mean for you. You do not need drawings or technical answers to call."],
 ["Straight answers, clear expectations.","We explain the options, the price and what the work will involve. If something needs further investigation, we say so and explain the next step. Being approachable matters to us: questions and concerns belong in the conversation, not at the end of it."],
 ["Local roots, projects further afield.","Our main focus is Meath, Louth and Dublin, with wider Leinster work considered individually. We also consider larger commercial solar projects across Ireland. Tell us your location and plans, and we will confirm whether we can help."]],["What you would like to improve","Your property and location","The questions you would like us to talk through"],[{"q":"Where is Fennor based?","a":"We are a family-run business based in Slane, Co. Meath. Our main area is Meath, Louth and Dublin, with wider Leinster enquiries considered individually and larger commercial solar projects considered across Ireland."},{"q":"Do I need a fully developed plan before contacting you?","a":"No. Tell us what you want to change and where the property is. We explain what information would help next, whether you have a developed plan or are only starting to explore."}],{"alt":"Slane Bridge reflected in the River Boyne, Co. Meath, with stone arches and trees along the riverbank","kind":"overview","related":["/about/your-project","/about/areas","/about/reviews","/contact"]}),
 '/about/your-project':make("Your project with Fennor","From first question","to a clear handover.","From the first question to the final handover, you need to know what is happening and who to call. Here is how Fennor helps you move your project forward, one clear step at a time.","full-home-editorial.webp",[
 ["We get the right starting picture.","We begin with your aims, location and the home or system you have now. We review any useful photographs, bills or drawings and explain whether the next step needs a visit or specialist assessment, including any cost."],
 ["We take you through the proposal.","You see what is included, the price, allowances and any exclusions. We explain the sequence, likely disruption and outstanding decisions, and identify who will handle required designs, permissions and grant steps. There is time to ask questions before you decide."],
 ["We keep the finish in view.","We agree your contact, progress updates and the process for changes at the start. The handover brings together the agreed documents, demonstrations and remaining items, with a clear route for aftercare questions."]],["What you want the project to achieve","Any plans or approvals already in place","How you would like to stay informed"],[{"q":"What happens if I want to change something?","a":"Tell us as soon as possible. We explain the effect on price, work and programme and record the agreed change before it proceeds, except where immediate safety action is required. The contract sets out that process."},{"q":"When would we agree the programme?","a":"We explain the likely sequence once the work, approvals and main dependencies are understood. Dates are agreed for your project, taking supply and site conditions into account."}],{"alt":"Architectural design concept of connected living spaces, from a considered project brief","feature":"journey","related":["/contact/assessment","/about/reviews","/advice"]}),
 '/about/reviews':make("Fennor reviews and customer feedback","Your experience matters.","Your questions are welcome.","You want to feel comfortable with the people working on your home. Ask us about relevant work, how we communicate and what happens after completion—or tell us about your own Fennor experience.","reviews-feedback-solar-home-v1.jpg",[
 ["Get to know the way we work.","Tell us which service you are considering. We will share the relevant project information available and answer your questions about the work, communication and handover. A useful example helps you understand the kind of job you are planning."],
 ["Understand your own proposal.","We take you through the work included, allowances, specialist appointments and warranty support. You have a chance to clarify the details and decide whether the plan fits your needs, rather than relying on a headline price."],
 ["Tell us how it went.","Your feedback and concerns are welcome by phone or email. We only publish customer names, photographs or testimonials with permission. Verified, customer-approved reviews will be added here as they become available."]],["The kind of project you are considering","What you would like to know about working with us","Any feedback from your own Fennor experience"],[{"q":"Where are the customer ratings?","a":"This new site does not yet display verified customer ratings. Contact us for the project information currently available. We will only publish genuine, customer-approved reviews."},{"q":"Can I raise a concern directly?","a":"Yes. Call 089 403 2737 or email info@fennor.ie with the project reference and what has happened. You do not need to make your personal project details public to contact us."}],{"alt":"Welcoming completed Irish home with a neatly installed rooftop solar array","kind":"guide","related":["/about/your-project","/solar/projects-case-studies","/contact"]}),
 '/about/areas':make("Areas we serve: Slane, Navan, Meath & Louth","Based in Slane.","Built around your project.","Our first focus is home projects in Slane, Navan and across Meath and Louth, with Dublin enquiries also welcome. Share your town and the work you have in mind, and Fennor will confirm coverage and the next step for your enquiry.","cottage.webp",[
 ["Homes close to our Slane base.","Meath and Louth are our first focus for home solar, renovations, retrofits, heat pumps and building projects. We also welcome Dublin enquiries. We start with your property and plans, then confirm project fit, availability and the assessment needed."],
 ["Elsewhere in Leinster.","For projects further afield, we look at the type of work, travel and specialist needs together. Send your town and a short description; we will give you a clear answer on whether the project is one we can consider."],
 ["Commercial solar across Ireland.","We consider larger commercial solar enquiries nationwide. We begin with the premises, electricity-use pattern and available roof information, then explain whether a closer assessment is the appropriate next step."]],["Your town and county","The work you have in mind","How far along your plans are"],[{"q":"Can I enquire from anywhere in Meath?","a":"Yes. Fennor is based in Slane and welcomes home-solar, renovation, retrofit, heat-pump and building enquiries across Meath. Tell us your town and the work you have in mind. We confirm project fit, availability and any assessment requirements before arranging a visit."},{"q":"Do you offer every service nationwide?","a":"Meath and Louth are our first residential focus, with Dublin enquiries also welcome and wider Leinster projects considered individually. Larger commercial solar projects may be considered nationwide. We confirm coverage for your location and proposed work when you contact us."},{"q":"Do you need my full address straight away?","a":"A town or county is enough to begin. We will ask for the precise site address when it is needed for the next step; there is no need to send personal documents to check coverage."}],{"alt":"Fennor service areas: Meath, Louth and Dublin — architectural design concept","related":["/solar/domestic","/renovations","/retrofitting","/heat-pumps","/building","/solar/commercial"]}),
 '/advice':make("Homeowner guides and practical advice","A little knowledge.","A better next step.","Straight answers to the questions that come up when you are improving a home. Choose the subject that matters to you, then let Fennor help you turn the information into a useful next step.","renovations-02.webp",[
 ["Find an answer without learning a new language.","The guides explain solar, heating and building choices in everyday terms. Start with the problem you want to solve; you do not need to understand every product or technical term before asking us for help."],
 ["See how the improvements connect.","A roof repair can affect solar; new windows can affect insulation and fresh air. We help you see those connections and put your planned work in a sensible order, with the right professional assessment where it is needed."],
 ["Bring the question back to your home.","Tell us what is still unclear and share whatever property information you already have. We explain the options, the next assessment and any funding or permission steps relevant to your plans."]],["The improvement you are considering","What you would like to understand better","Any property information you already have"],[{"q":"Do I still need a survey after reading a guide?","a":"The guides explain the choices but cannot assess the property. We tell you which survey or specialist input your project needs and agree the next step with you."},{"q":"Can I ask Fennor about a grant I have seen?","a":"Yes. Share the announcement and what you want to improve. We explain the relevant route and the conditions to check; the administering body’s current terms and your written offer determine support."}],{"alt":"Homeowner guides and practical advice — architectural design concept","kind":"overview","related":["/solar/faq-advice","/heat-pumps/faq","/renovations/older-homes","/advice/grant-updates","/advice/news"]}),
 '/advice/grant-updates':make("Grants & funding in Ireland","The support available.","For your next step.","Explore solar, electrical, energy-efficiency, heat-pump, insulation and renovation support in one place. Filter the current guide, then talk to Fennor about the conditions and the next step for you.","domestic-white-house-18-panels.webp",[
 ["Solar and battery support at home.","The standard solar PV maximum is €1,800, with separate €600 support for an eligible battery. Enhanced support of up to €9,000 is a different eligibility route. We explain the breakdown and which property or previous-funding conditions matter for your enquiry."],
 ["The business solar application window.","SEAI lists enhanced NDMG applications from 6 October 2026 to 6 July 2027. That nine-month window is for applications; completion follows the grant offer. We work through your electricity use and proposed system before explaining the eligible-cost and size limits."],
 ["Support for a warmer home.","Windows, doors, insulation, heating controls and heat-pump support depends on the home, existing system and proposed work. We explain the relevant individual grants, approval sequence and registered roles alongside the improvements Fennor can cover."],
 ["Electrical and business energy support.","A home EV charger or qualifying heating-controls upgrade can have specific support. For a business, metering, controls, AHU, pump and larger energy projects have different schemes. Routine rewiring, testing, repairs and maintenance do not have a general grant, so we keep the supported measure and ordinary electrical work clear."]],["The improvement or announcement you want to discuss","Your home or premises and any previous grants","Any application or offer already in progress"],[{"q":"How current is this guidance?","a":"This guide was checked against official sources on 14 October 2026 and does not update automatically. We help explain the route, but current official terms and your written offer determine your project’s support."},{"q":"Can the work start as soon as a grant is announced?","a":"Not automatically. We explain the application and approval steps for your chosen route, including restrictions on purchases. The required approval must be in place before work begins."}],{"alt":"Architectural visualisation of a white home with rooftop solar panels overlooking a rural landscape","kind":"guide","sources":[["SEAI current home upgrade routes","https://www.seai.ie/homeenergyupgrades"],["SEAI business grants and supports","https://www.seai.ie/grants/business-grants"],["SEAI commercial solar grant","https://www.seai.ie/grants/business-grants/commercial-solar-pv"]],"related":["/electrical/domestic","/electrical/commercial","/electrical/industrial-maintenance","/solar/grants-funding","/heat-pumps/grants","/retrofitting/grants-funding"]}),
 '/advice/news':make("Fennor news and home-improvement insights","Worth knowing.","Worth thinking through.","Ideas worth bringing into your next home project: useful energy updates, practical renovation choices and small decisions that can make a difference to everyday living.","home-detail.webp",[
 ["9 October 2026 · A reason to revisit an upgrade.","New grant support may make a project worth another look. Tell Fennor what you had in mind and we will explain the relevant route and assessment, alongside the actual work and budget—not just the headline amount."],
 ["9 October 2026 · Renovating now, planning energy for later.","Opening a wall or floor is a useful time to think about future charging, heating or solar. We help identify service routes worth considering in the renovation, without asking you to buy equipment before its specification is known."],
 ["9 October 2026 · Bring the image that caught your eye.","A bright kitchen or a garden-facing room can be the easiest way to explain what you want. We ask what you like about it—light, materials or layout—and use that to shape your own brief. Design concepts are labelled as inspiration, not completed customer work."]],["An idea or image that caught your attention","What you would like to change at home","The question you want to explore with us"],[{"q":"Can I use the images to explain what I would like?","a":"Yes. Show us the image and tell us which part appeals to you. We use it to understand your preferences, then work through what fits your home, budget and the relevant assessment."},{"q":"Where can I go deeper into a subject?","a":"Follow the linked service guides for more detail, or contact Fennor with the question. We will explain what it means for your plans and what information is useful next."}],{"alt":"Fennor news and home-improvement insights — architectural design concept","kind":"guide","related":["/advice/grant-updates","/solar/projects-case-studies","/about/your-project"]}),
 '/contact':make("Contact Fennor Developments","Tell us what","you have in mind.","Tell us what you would like to change. A few lines about the property, your location and the problem you want to solve are enough to start with Fennor.","renovations-02.webp",[
 ["Start with the basics.","Your town, the type of project and what matters most to you give us a useful first picture. Add photographs or drawings if you already have them, but there is no need to prepare a full specification."],
 ["We explain what happens next.","We review your enquiry and identify whether a phone conversation, further information or an assessment is the right next step. Any visit, its purpose, availability and cost are agreed directly with you."],
 ["Keep the first message simple.","We do not need welfare records, bank details or identity documents in your first enquiry. If further information is required, we will explain why and how it relates to your project."]],["Town or county","Project type and priorities","Your preferred contact method"],[{"q":"How do I send my enquiry?","a":"Complete the form and select its send button. A confirmation appears when the email service accepts your message for delivery. If it cannot be sent, the form explains the problem and keeps your details available. You can also email info@fennor.ie directly or call 089 403 2737."},{"q":"Can I attach photographs?","a":"The website form accepts text, not attachments. Email photographs or drawings to info@fennor.ie, including your name and project area. Take photographs only from safe, accessible ground-level positions. Do not climb onto a roof."}],{"alt":"Contact Fennor Developments — architectural design concept","kind":"contact","related":["/contact/assessment","/about/areas"]}),
 '/contact/assessment':make("Request a Fennor project assessment","A clearer picture.","A better proposal.","Let’s get a clearer picture of your property. Fennor will explain the assessment your plans need, who will carry it out and any cost before a visit is agreed.","full-home-editorial.webp",[
 ["For a solar or battery enquiry.","We start with your electricity use, existing equipment and plans for charging or heating. Bills and safely taken roof photos can help, and we will tell you what is needed for the assessment without asking for sensitive account details."],
 ["For a renovation or building project.","We review the changes you want, the drawings available and any known concerns. We then explain the survey or design information needed to move towards a price, including access and whether you need to stay living at home."],
 ["For a warmer, more comfortable home.","We start with the rooms that feel cold and the heating you use now. A BER or insulation history helps if available. We explain the technical assessment required; the online checklist simply helps prepare the conversation."]],["The property and change you have in mind","Whatever photographs or documents you already have","What you would like the assessment to clarify"],[{"q":"Does this enquiry book the assessment?","a":"No. It starts your enquiry. We agree the appointment, professional assessment, availability and any fee directly before booking a visit."},{"q":"Will photographs be enough?","a":"They are a useful start. We explain what they tell us and which site, structural, electrical or heating checks still need an assessment in person or the relevant professional review."}],{"alt":"Architectural design concept of an Irish home with coordinated living spaces","kind":"contact","related":["/about/your-project","/solar/calculator","/heat-pumps/suitability"]}),
 '/solar':make("Solar PV for Homes, Farms & Business","Make more","of your daylight.","From our Slane base, Fennor helps homeowners, farms and businesses in Navan and across Meath and Louth plan solar around the electricity they use. Explore panels, storage and controls for your property, with larger commercial enquiries considered across Ireland.","solar-overview-editorial.webp",[
 ["We start with the bill and the daily routine.","When you use electricity matters as much as the annual total. We review your use, daytime activity and future plans so the first recommendation reflects your property, rather than a standard panel package."],
 ["We help you choose the right combination.","We explain panels, the inverter, optional storage and accessories against your needs and budget. The site and electrical assessment establish what is suitable, including the roof or land, connection and equipment compatibility."],
 ["You understand the proposal before deciding.","We take you through the equipment, estimated output, funding route and installed price. We explain the savings assumptions separately from warranties and make the handover and aftercare arrangement clear."]],["Recent bills and when you use most electricity","Any safely taken roof or site photographs","Future EV, heat-pump or extension plans"],[{"q":"Where should I start if I know very little about solar?","a":"Call or email with your location and what you want solar to achieve. We explain the basics, the useful information to gather and the assessment needed for your property."},{"q":"Will I need a battery as well?","a":"Not always. We compare solar alone with storage using your demand, surplus and tariff. If a battery has a useful role, we explain its cost, losses and compatibility rather than treating it as an automatic extra."}],{"alt":"Architectural design concept of a white Irish home with rooftop solar panels in a countryside setting","kind":"overview","related":["/solar/domestic","/solar/commercial","/solar/farm","/solar/ground-mounted","/solar/battery-storage","/solar/accessories","/solar/calculator","/solar/grants-funding","/solar/projects-case-studies","/solar/faq-advice"]}),
 '/solar/accessories/eddi':make("EDDI solar hot-water diverter","From spare sunlight.","To a warmer cylinder.","Put spare solar electricity towards the hot water you use at home. Fennor helps you work out whether EDDI suits your cylinder and where it fits alongside a battery, charging or export.","accessory-eddi.webp",[
 ["Understand what EDDI would do.","EDDI adjusts a compatible resistive heating load to use available surplus. myenergi specifies diversion up to 3.7 kW. We explain how that differs from switching on a full-power immersion; the existing cylinder thermostats and safety controls remain essential."],
 ["We begin with your current hot water.","We ask about the cylinder, immersion and how your household uses water. The electrical assessment then establishes compatibility, grid-flow measurement and installation details. We explain the work and cable routes before you choose the accessory; a home without a cylinder is not an automatic fit."],
 ["We put the priorities in order.","We compare water-heating value with the export payment you would give up. Where you have a battery or EV, we include those needs too. Correctly coordinated controls prevent unintended battery draining, and a heat pump may heat water more efficiently than an immersion."]],["How your household heats and uses hot water","Cylinder and immersion details if available","Your solar, battery and export tariff"],[{"q":"Would EDDI make all my hot water free?","a":"No. Its contribution depends on surplus, season and water use. A boost can import electricity, and power used for water cannot also be exported. We explain those trade-offs using your household’s routine."},{"q":"Can I include EDDI with a battery?","a":"Potentially. We review the equipment details and explain the required compatibility and control checks. The installer then establishes the measurements and priorities; an on-screen energy flow is not a wiring design."},{"q":"Could it be added to my existing solar?","a":"Often. We start with the cylinder, solar equipment and electrical installation, then explain the assessment and installation work needed for a suitable addition."}],{"alt":"myenergi EDDI hot-water diverter, manufacturer product image","kind":"product","feature":"surplus","sources":[["myenergi: what EDDI does","https://support.myenergi.com/hc/en-gb/articles/22681298060305-What-Does-eddi-Do"],["myenergi EDDI product guidance","https://www.myenergi.com/ie/eddi-power-diverter"]],"related":["/solar/accessories","/solar/battery-storage","/heat-pumps/with-solar"]}),
 '/solar/accessories/backup-power':make("Solar backup power and changeover switches","When the grid stops.","Know what stays on.","Want the lights, fridge or internet to stay on during a power cut? Fennor helps you define the essentials and understand the equipment and electrical design needed to support them.","accessory-changeover.webp",[
 ["We work out what matters most.","A fridge and lights need a different plan from an electric shower or cooker. We help list the loads and desired duration, then explain the difference between stored energy, simultaneous power and starting currents."],
 ["We establish the safe design route.","A battery and changeover switch are not a complete backup system. A Registered Electrical Contractor must design the inverter supply, isolation, protection and earthing so it cannot energise the public network during an outage. We explain that specialist work as part of the project; it is not DIY."],
 ["You know how backup will behave.","We explain manual or automatic operation, supported circuits and the limits of the chosen equipment. Automatic transfer does not necessarily mean uninterrupted power. Battery reserve, output and outage duration matter, and backup must never be assumed suitable for life-critical equipment."]],["The appliances or circuits that matter most during an outage","Any existing inverter and battery model details","Whether you expect manual or automatic changeover"],[{"q":"Would my normal solar keep working in a power cut?","a":"Ordinary grid-connected solar shuts down for safety. Backup needs compatible equipment and properly designed isolation. We review what you have and explain the assessment needed to establish the options."},{"q":"Would the pictured switch suit my system?","a":"Not necessarily. It is a Hager example, not a universal solution. We use the complete electrical design to establish suitable equipment; a switch cannot make an incompatible inverter operate off-grid."},{"q":"Could backup serve my whole home?","a":"Only where the design supports it. Many systems supply selected circuits. We make the supported and excluded loads clear, along with the power and energy limits, before you choose an arrangement."}],{"alt":"Hager manual changeover switch, manufacturer product image","kind":"product","sources":[["SEAI: solar panels and power cuts","https://www.seai.ie/blog/solar-panels-power-cut"]],"related":["/solar/battery-storage","/solar/accessories","/contact/assessment"]}),
 '/solar/accessories/ev-charging':make("Solar-aware EV charging at home","Your roof.","Your next journey.","Come home, plug in and charge around your routine. Fennor helps you plan a home charger around the car, driveway, electricity supply and any solar you already have.","accessory-zappi-installed.webp",[
 ["We explain the charging choices.","myenergi zappi offers FAST, ECO and ECO+ modes, using grid power and available surplus differently. We relate those options to when you need the car ready. Solar is optional; compatible charging can use grid electricity when needed."],
 ["We plan the practical installation.","We start with parking, cable reach and the car’s arrival and departure times. The electrical assessment establishes supply and load-management requirements. The vehicle’s onboard charger and minimum charging needs also matter; solar cannot charge a car while it is away."],
 ["We explain the grant steps.","SEAI offers up to €300 for an eligible home charger. It requires an eligible smart charger and a Safe Electric Registered Electrical Contractor, with the offer in place before the relevant costs or work. We explain the application sequence alongside your installation plan."]],["Where you park and when the car is normally home","Your vehicle or planned EV","Any existing solar and your current electricity tariff"],[{"q":"Would I need solar panels for zappi?","a":"No. It can charge from the grid. We explain which solar-aware functions apply where compatible generation and measurement are present, or plan charging without solar."},{"q":"Could solar cover all my driving?","a":"It depends on mileage, vehicle efficiency, connection times and available surplus. We work through those patterns with you, including seasonal changes and grid charging when solar is not enough."},{"q":"Would the charger grant be included automatically?","a":"No. Property, equipment, contractor and application conditions apply. We explain what needs approval and when, so the required grant offer is in place before the relevant purchase or work."}],{"alt":"White myenergi zappi EV charger and looped cable mounted on dark exterior cladding, manufacturer photograph","kind":"product","sources":[["myenergi zappi: photograph credit, modes and product information","https://www.myenergi.com/ie/zappi-car-charger"],["SEAI home-charger grant","https://www.seai.ie/grants/electric-vehicle-grants/electric-vehicle-charging/electric-vehicle-home-charger-grant"]],"related":["/solar/domestic","/solar/accessories/eddi","/solar/battery-storage"]}),
 '/solar/calculator':make("Solar panel size and value calculator","Play with the numbers.","Start the conversation.","Try a few panel counts and see how electricity use changes the numbers. Then bring the result to Fennor for a closer look at your roof and routine. These are planning examples, not a design or quotation.","domestic-white-outbuilding.webp",[
 ["We help turn panel counts into a real layout.","kWp is nominal panel capacity under test conditions, not annual generation. Yearly kWh depend on location, orientation, tilt, shading and losses. We explain the site assessment needed to move from the example to a system for your property."],
 ["See the difference between using and exporting.","Power used at home can avoid imports at your unit rate; export earns a separate rate. Try your actual tariffs on a consistent VAT basis. The illustration excludes export caps, curtailment and standing charges, and does not count battery savings twice."],
 ["We put the result beside the full cost.","A proper appraisal includes installed cost, eligible support, maintenance, degradation, future tariffs and the time value of money. The tool does not promise a payback period. We explain the assumptions and next information needed for your own proposal."]],["Recent electricity use, ideally covering a year","Your import and export unit rates","The result or question you would like to discuss"],[{"q":"Does the illustrated panel layout show what fits on my roof?","a":"No. It illustrates the count. We explain the assessment required for roof dimensions, structure, clearances and shading before a layout can be established."},{"q":"Are the starting numbers a forecast for my home?","a":"No. The defaults explain the arithmetic. We use your demand, tariff and a site-specific generation estimate for a meaningful property-specific discussion."}],{"alt":"Solar panel size and value calculator — architectural design concept","feature":"calculator","related":["/solar/domestic","/solar/battery-storage","/contact/assessment"]}),
 '/solar/grants-funding':make("Solar grants and battery funding in Ireland","The right support.","For your circumstances.","Solar support differs for a home, business or farm. Fennor helps you understand the route for your project, the costs it may cover and the approval steps needed before work begins.","solar-home.webp",[
 ["Standard home solar and storage.","Solar PV support is capped at €1,800. An eligible battery of at least 5 kWh has separate €600 support: a possible combined maximum of €2,400 when both apply. We explain the property and previous-funding conditions alongside your proposed system."],
 ["The enhanced household route.","Up to €9,000 means up to €8,400 for PV and €600 for an eligible battery, not an addition to the standard PV grant. Qualifying welfare recipients can apply. The separate Dublin Rental Accommodation Scheme pilot requires eligible landlords to obtain confirmation from the relevant Dublin local authority."],
 ["Business and farm projects.","We start with your premises and electricity use, then explain SEAI NDMG and, for farms, DAFM’s Solar Capital Investment Scheme. The same investment cannot be funded twice. We explain the selected route’s required approval sequence before the project moves to work."]],["The property and type of solar project","Any previous support or application already underway","The system and budget you would like to discuss"],[{"q":"Would I be looking at €2,400 or €9,000?","a":"They are different routes. Up to €2,400 combines standard PV and eligible battery support; up to €9,000 belongs to the enhanced eligibility-based route. We explain the conditions relevant to you, with the scheme determining the award."},{"q":"How would the grant affect what I pay?","a":"We show the project cost and possible support separately, then explain who applies, pays the invoice and claims the funding. Payment differs by scheme; a grant is not automatically an immediate discount or money available before work."}],{"alt":"Solar grants and battery funding in Ireland — architectural design concept","kind":"guide","feature":"grants","sources":[["SEAI solar PV grant","https://www.seai.ie/grants/home-energy-grants/individual-grants/solar-electricity-grant"],["SEAI battery grant","https://www.seai.ie/grants/home-energy-grants/individual-grants/battery"],["SEAI higher support routes","https://www.seai.ie/homeenergyupgrades"],["SEAI business solar","https://www.seai.ie/grants/business-grants/commercial-solar-pv"]],"related":["/solar/domestic#funding","/solar/commercial#commercial-grant-tool","/solar/farm#farm-grants","/advice/grant-updates"]}),
 '/solar/faq-advice':make("Solar panel FAQ and advice for Irish homes","Good questions.","Clearer solar decisions.","Will solar work on your roof? What does a battery add? How much power will you still buy? Fennor explains the choices in plain language and helps you take the next step for your own property.","domestic-white-outbuilding.webp",[
 ["We make the numbers easier to follow.","kWp describes nominal panel capacity, kW is power at a moment and kWh is energy over time. We use your proposed equipment to explain the difference, so inverter power and battery storage are not treated as the same figure."],
 ["You see what sits behind the estimate.","We explain expected generation, direct use, export and tariffs alongside the system price. The estimate reflects the assumptions about your routine, and we show why a change in daytime use could affect the result."],
 ["We look after the roof questions too.","Tell us about planned repairs or anything that concerns you. We identify the condition, structural and shading checks needed, then explain access, cable routes, weatherproofing and maintenance in the proposed installation."]],["Your roof and any planned repairs","When you use electricity and what might change","The questions you would like Fennor to explain"],[{"q":"Do panels work when it is cloudy?","a":"Yes, PV can generate in diffuse daylight, usually less than in strong sunlight. Weather, season and shading affect output. We explain those factors in the site-specific estimate."},{"q":"Does my roof have to face south?","a":"No. Other directions can work with different generation patterns. We establish the site assessment needed instead of ruling a roof out by direction alone."},{"q":"Would solar remove my electricity bill?","a":"Usually not. Imports, standing charges and other charges can remain. We explain the expected balance between generation, use and export using your tariff and routine."},{"q":"What would the handover include?","a":"We set out the agreed equipment records, applicable electrical certification, grid-notification evidence, commissioning, warranties and operating guidance. We also explain who will handle your aftercare questions."},{"q":"Should I include a battery now or later?","a":"We explain both options using your demand, surplus, tariff and equipment compatibility, including whether later expansion is practical. A battery needs a useful purpose, not just a place on the quote."}],{"alt":"Solar panel FAQ and advice for Irish homes — architectural design concept","kind":"guide","sources":[["SEAI solar electricity guidance","https://www.seai.ie/renewable-energy/solar-energy/electricity-from-solar"]],"related":["/solar/calculator","/solar/domestic","/solar/battery-storage","/solar/accessories"]}),
};

// Keep inspiration useful to homeowners without presenting concepts as completed work.
Object.assign(editorialPages,{
 '/solar/cost':make("Solar panels cost Ireland 2026","What does solar cost?","Start with a complete quotation.","There is no responsible one-price answer for every roof. Fennor explains what changes the installed cost, how current grants fit and what a useful solar quotation should include before you compare totals.","domestic-clean-array.webp",[
 ["A useful Irish benchmark — with context.","A 2026 market report based on SEAI Solar PV Scheme data puts the average pre-grant cost of grant-supported systems installed in 2025 at €10,529, with an average size of 6.23 kWp. Its estimates are about €9,450 without a battery and €12,800 with one. These are historic market averages across different homes and specifications, not a Fennor price list or a quotation for your property."],
 ["The roof and electrical work shape the price.","A quotation needs the measured layout, access, roof condition, cable route and the findings for the existing electrical installation. Extra panels are only one part of cost; scaffolding, protection, distribution work and making good can matter too."],
 ["Equipment needs a named specification.","We show the proposed panel, inverter, mounting system and any battery or accessories, including their capacities and warranties. That lets you compare what is actually being supplied rather than treating two different systems as the same package."],
 ["Grants reduce eligible cost, not design responsibility.","Eligible domestic PV can receive up to €1,800 and an eligible battery of at least 5 kWh can receive up to €600 under the current 2026 routes. We show the full installed price and possible support separately; SEAI eligibility and approval determine the award."],
 ["Savings need assumptions you can inspect.","The appraisal separates expected generation, direct use, export and tariff assumptions. We do not turn the most optimistic scenario into a guaranteed payback. You can see what changes if your routine, electricity price or export value changes."]
 ],["A recent electricity bill and your current tariff","Safe photographs and any known roof concerns","The systems, battery options or quotations you want to compare"],[
 {q:"How much do solar panels cost in Ireland in 2026?",a:"As a dated market benchmark, a 2026 report based on SEAI scheme data gives an average pre-grant cost of €10,529 for systems installed in 2025, averaging 6.23 kWp. It estimates about €9,450 without a battery and €12,800 with one; the national average was €1,689 per kWp and the Meath average €1,725 per kWp. These figures cover different properties and specifications and are not a current Fennor quotation. Your roof, access, electrical work, equipment and storage choice determine the actual price."},
 {q:"How much is the standard solar grant?",a:"The current standard domestic Solar PV grant is capped at €1,800. An eligible battery of at least 5 kWh can have separate support of up to €600. Property, previous-funding, provider and approval conditions apply; the scheme administrator determines the award."},
 {q:"Is the cheapest solar quotation the best value?",a:"Not necessarily. Compare the roof assessment, named equipment, system design, installation work, electrical upgrades, output assumptions, monitoring, warranties, exclusions and aftercare. We take you through those lines before asking you to decide."},
 {q:"Does a battery always improve the payback?",a:"No. A battery adds cost and conversion losses. Its value depends on available surplus, evening demand, time-of-use tariffs, export value and what else you want storage to do. We compare solar alone and storage rather than treating a battery as automatic."}
 ],{"alt":"Neatly aligned black solar panels on an Irish slate roof","kind":"guide","sources":[["2026 Irish residential solar market report (2025 installation data)","https://energyefficiency.ie/wp-content/uploads/2026/04/Residential-Solar-Panel-Report-2026.pdf"],["SEAI home Solar PV grant","https://www.seai.ie/grants/home-energy-grants/individual-grants/solar-electricity-grant"],["SEAI battery grant","https://www.seai.ie/grants/home-energy-grants/individual-grants/battery"]],"related":["/solar/calculator","/solar/domestic","/solar/grants-funding","/contact/assessment"]}),
 '/solar/projects-case-studies':make("Solar projects & case studies","Solar projects.","Picture your own potential.","Explore original solar photographs and picture the possibilities for your own property. Fennor helps you understand the roof, equipment and everyday electricity use behind a suitable system.","domestic-white-outbuilding.webp",[
 ["Start with the space you have.","A main roof, outbuilding or suitable area of land can open different possibilities. We review your property details and identify the site assessment needed, rather than copying a panel count from a photograph."],
 ["See beyond the panels.","We explain where the inverter, optional battery and controls would fit and how they would serve the property. Access, appearance and your priorities for hot water or charging are part of that conversation."],
 ["Bring it back to your own electricity use.","We review when you use power and what may change in the future. That gives the proposed system a purpose and gives you a clear starting point for the output estimate and price."]],["A photograph or feature that interests you","Your roof or site and daily electricity use","What you would like solar to achieve"],[{"q":"Are these full customer case studies?","a":"These are supplied site and equipment photographs, not full customer case studies. Installation dates, system sizes and savings have not been attributed without confirmed details."},{"q":"Could something similar work on my roof?","a":"Send your location and safely taken photographs. We will explain the assessment needed and the options worth exploring for your roof and electricity routine."}],{"alt":"Supplied photograph of a slate-roofed outbuilding with solar panels","kind":"project","related":["/solar","/about/your-project","/contact"]}),
 '/renovations/projects-case-studies':make("Renovation projects & case studies","Renovation ideas.","For the way you live.","A brighter kitchen, a calmer bathroom or a better connection to the garden. Use these design concepts to show Fennor the direction you like, and we will help shape a plan for your own home.","renovation-overview-photoreal-v2-4k.webp",[
 ["Show us the detail you love.","It might be the natural materials, generous storage or the way two rooms connect. We ask what appeals to you and what currently gets in the way at home, then turn those preferences into a practical brief."],
 ["Make the idea work in your rooms.","We identify the measurements, services and design checks needed for the change. In a bathroom, that includes water, drainage and ventilation; in a kitchen, it includes how the layout works around your routine."],
 ["Choose what matters within your budget.","You do not need every detail from an image. We help prioritise the useful changes and explain the work and price, so the finished plan reflects your home rather than a copied concept."]],["Images or materials you like","The rooms and routines you want to improve","Your priorities and comfortable budget range"],[{"q":"Are the images completed Fennor renovations?","a":"No. These are design concepts for inspiration, not completed Fennor renovations."},{"q":"Can I use one of these concepts as a starting point?","a":"Yes. Show us what you like and a little about your existing rooms. We help form the brief and explain the survey and design steps needed to take it forward."}],{"alt":"Renovation inspiration showing connected kitchen, dining and family living spaces","kind":"project","related":["/renovations","/about/your-project","/contact"]}),
 '/retrofitting/projects-case-studies':make("Retrofit projects & case studies","A warmer home.","Picture what could change.","Picture a home that feels warmer and works better day to day. These retrofit design concepts are a starting point; Fennor helps you turn your own comfort problems into a practical upgrade plan.","retrofit-03.webp",[
 ["Tell us where comfort is missing.","Cold corners, draughts and heating costs give us a useful starting point. We review what you know about the home and explain the assessment needed to establish which improvements are suitable."],
 ["We connect the improvements.","Windows, insulation, ventilation and heating affect each other. We explain how the proposed changes fit together, including the building-specific design needed at the connections between them."],
 ["You choose a manageable next step.","We help prioritise staged or whole-home work around your budget and daily life. You see the proposed improvements, likely disruption and relevant funding route before deciding how to proceed."]],["The comfort problems you want to solve","Any BER or previous upgrade information","Whether you prefer staged work or a whole-home project"],[{"q":"Are these completed customer retrofits?","a":"No. The images are design concepts, not completed customer projects or proof of a particular BER or energy saving."},{"q":"How do I start a similar upgrade?","a":"Tell us what feels uncomfortable and which improvement interests you. We explain the assessment, the likely project steps and the information needed to take the next step."}],{"alt":"Retrofit design concept of a comfortable home with improved windows and heating","kind":"project","related":["/retrofitting","/about/your-project","/contact"]}),
});
const buildingGuidance:[string,string]=['Irish building-regulation technical guidance','https://www.gov.ie/en/collection/d9729-technical-guidance-documents/'];
